SELECT 'gongkao', '间隔增长', 'kp-xingce-data-growth-interval', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "间隔增长"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "跨越一个中间年份的复合增长率计算。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "当题目问：“2023年相比于2021年（跨越了2022年）增长了百分之多少？”时，考的就是间隔增长率。特征：时间跨度为2年，且问的是比率。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心公式"}]}, {"type": "katexBlock", "attrs": {"content": "R = r_1 + r_2 + r_1 \\times r_2"}}, {"type": "paragraph", "content": [{"type": "text", "text": "公式组成：r1为现期增速，r2为基期增速，后面一项为交叉乘积。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[圈出年份确认是间隔增长] --> B[在材料里找出 r1 和 r2]\nB --> C[算前两项之和: r1 + r2]\nC --> D{判断尾项 r1*r2 的影响}\nD -- 双小 --> E[忽略尾项, 约等于和]\nD -- 极大 --> F[算出尾项具体数值并加上去]\nD -- 一正一负 --> G[尾项必为负, 结果略小于和]\nF --> H[得出最终 R]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题完整推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 2023年某省GDP同比增长15%，2022年同比增长10%。求2023年相对2021年的增速？选项：A. 25.0% B. 26.5% C. 28.3% D. 30.1%"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "识别：求2023比2021的增速，即间隔增长率。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "找数据：r1 = 15%，r2 = 10%。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "算加法：15% + 10% = 25%。如果忽略尾项就是 25%。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "判尾项：两个都是正数，且不算太小。尾项 = 15% × 10% = 1.5%。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "汇总：R = 25% + 1.5% = 26.5%。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "锁定答案：选 B。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "负增长率漏掉负号：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "如果 2022 年下降了 5%，代入公式时必须写成 r2 = -5%。尾项乘积就是负数！很多同学忘带负号，直接全部用加法，满盘皆输。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "强化尾项 10% × 10% = 1% 这种百分数乘法的数量级概念。不要把 10%×20% 算成 20%！"}]}]}$$ AS jsonb), NULL, '间隔增长的核心考点与实战推导。', category_node.id, CAST('["资料分析", "间隔增长"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_data_growth_interval", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
